  const rrO1 = (tp1 - trig) / (trig - stopOrd), rrO2 = (tp2 - trig) / (trig - stopOrd), rrC1 = (tp1 - cap) / (cap - stopOrd), rrC2 = (tp2 - cap) / (cap - stopOrd);
  const riskSh = cap - stopOrd;
  // Écart d'ouverture le plus défavorable sur un an, mesuré depuis la clôture de la veille, et pire séance de clôture à clôture.
  let worstGap = 0, worstGapD = ''; for (let i = Math.max(1, N - 251); i <= N; i++) { const gp = bars[i][1] / bars[i - 1][4] - 1; if (gp < worstGap) { worstGap = gp; worstGapD = bars[i][0]; } }
  let worstDay = 0, worstDayD = ''; for (let i = Math.max(1, N - 251); i <= N; i++) { const d = bars[i][4] / bars[i - 1][4] - 1; if (d < worstDay) { worstDay = d; worstDayD = bars[i][0]; } }
  const wg = bars.findIndex(b => b[0] === worstGapD), gapPrevClose = bars[wg - 1][4], gapOpenPx = bars[wg][1], gapPrevDay = pct(bars[wg - 1][4], bars[wg - 2][4]);
  const wd = bars.findIndex(b => b[0] === worstDayD), wdOpen = bars[wd][1], wdPrevClose = bars[wd - 1][4];
  // Taille : un saut égal au pire écart d'ouverture, depuis une clôture juste au-dessus du stop, ouvre sous le stop ; la
  // perte par action au plafond se mesure jusqu'à ce prix d'ouverture.
  const gapThreshold = stopOrd / (1 + worstGap), gapOpenFromStop = stopOrd * (1 + worstGap), gapLossSh = cap - gapOpenFromStop;
  const sizeStop = Math.floor(1000 / riskSh), sizeGap = Math.floor(1000 / gapLossSh), gapCostAtStopSize = sizeStop * gapLossSh;
